import {RANKS,rankFor,rankLabel} from './ranks.js';
import './reading.js';
import {reviewMoment,legalLine,recordSignature} from './review-engine.js';
import {newGame,play,score,groupAt,LEVELS,chooseMove} from './engine.js';
import {chooseStrongMove,analyzeStrongPosition,cancelStrongSearch} from './strong-engine.js';
const APP_VERSION='2.0.0';
const $=id=>document.getElementById(id),KEY='yongdam-v1',ARCHIVE='yongdam-archive-v1';
const letters='ABCDEFGHJKLMNOPQRST',NS='http://www.w3.org/2000/svg';
const defaults={size:19,level:6,rank:'1d',color:1,handicap:0,komi:6.5,confirm:matchMedia('(pointer:coarse)').matches};
let settings={...defaults},state,states=[],gameId='',createdAt='',result=null,dead=new Set(),archive=[],review=null,reviewIndex=0,pending=null,hintIndex=null,focusIndex=0,numbers=false,coords=true,sound=true,busy=false,worker=null,jobId=0,jobKind='',offlineReady=false,installPrompt=null,storageWarned=false,enginePhase='',engineStats=null,engineFailure=false;
function safeRead(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function saveStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{if(!storageWarned){storageWarned=true;toast('저장 공간이 부족합니다. 기보를 내려받아 보관해 주세요.')}return false}}
function validateSettings(raw={}){return {rank:rankFor(raw),size:[9,13,19].includes(raw.size)?raw.size:19,level:Math.max(0,Math.min(6,Number(raw.level)||0)),color:raw.color===2?2:1,handicap:Math.max(0,Math.min(raw.size===9?5:9,Number(raw.handicap)||0)),komi:[0,.5,6.5,7.5].includes(raw.komi)?raw.komi:6.5,confirm:typeof raw.confirm==='boolean'?raw.confirm:defaults.confirm}}
function rebuild(record){const opt=validateSettings(record.settings);let s=newGame(opt.size,opt.handicap),stack=[s];for(const m of record.moves||[]){const r=play(s,typeof m==='number'?m:m.index);if(!r.ok)throw new Error('기보 형식 오류');s=r.state;stack.push(s)}return {settings:opt,state:s,states:stack}}
function record(){return {version:1,id:gameId,date:createdAt,updatedAt:new Date().toISOString(),settings,moves:state.moves.map(m=>m.index),result,dead:[...dead]}}
function persist(){const ok=saveStorage(KEY,record());$('save-indicator').textContent=ok?'자동 저장됨':'저장 불가';if(result)saveArchive(record())}
function saveArchive(rec){if(!rec.moves.length&&!rec.result)return;archive=archive.filter(a=>a.id!==rec.id);archive.unshift(rec);archive=archive.slice(0,30);saveStorage(ARCHIVE,archive)}
function reset(opt){cancelAI();settings=validateSettings(opt);state=newGame(settings.size,settings.handicap);states=[state];gameId=globalThis.crypto?.randomUUID?.()||String(Date.now());createdAt=new Date().toISOString();result=null;dead=new Set();review=null;pending=null;hintIndex=null;focusIndex=0;engineStats=null;persist();render();queueAI()}
function showTab(name){document.querySelectorAll('.tab-page').forEach(el=>el.hidden=el.id!==name+'-tab');document.querySelectorAll('.nav-button').forEach(el=>el.classList.toggle('active',el.dataset.tab===name));if(name==='archive')renderArchive();location.hash=name}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3300)}
function info(title,html,actions=[]){$('info-title').textContent=title;$('info-content').innerHTML=html;$('info-actions').replaceChildren();actions.forEach(({label,action,primary})=>{const b=document.createElement('button');b.className='button'+(primary?' primary':'');b.textContent=label;b.onclick=()=>{$('info-dialog').close();action?.()};$('info-actions').append(b)});if(!actions.length){const b=document.createElement('button');b.className='button primary';b.textContent='알겠습니다';b.onclick=()=>$('info-dialog').close();$('info-actions').append(b)}$('info-dialog').showModal()}
function cancelAI(){stopReviewAnalysis();jobId++;busy=false;worker?.terminate();worker=null;cancelStrongSearch();enginePhase='';engineFailure=false}
function runAI(kind){
 if(busy||review||result||state.finished)return;
 busy=true;engineFailure=false;jobKind=kind;const id=++jobId;let done=false;enginePhase=settings.level>=4?'loading':'searching';render();
 const finish=(index,stats=null)=>{if(done||id!==jobId)return;done=true;busy=false;enginePhase='';engineStats=stats;worker?.terminate();worker=null;if(kind==='hint'){hintIndex=index;toast(index<0?'더 둘 곳이 없다면 한 수 쉬기를 선택해 보세요.':coord(index,state.size)+' 자리를 생각해 보세요.');render()}else makeMove(index,true)};
 const failure=error=>{if(done||id!==jobId)return;done=true;busy=false;enginePhase='';engineFailure=true;cancelStrongSearch();render();info('강화 엔진을 다시 준비해 주세요','<p>강화 엔진이 이번 수를 계산하지 못했습니다. 인터넷 연결 상태에서 한 번 다시 시도해 주세요. 엔진 준비가 끝나면 오프라인에서도 사용할 수 있습니다.</p><p>대국은 자동 저장되어 있습니다.</p>',[{label:'다시 시도',primary:true,action:()=>runAI(kind)},{label:'기보 내려받기',action:()=>downloadSGF(record())}])};
 if(settings.rank||settings.level>=4){
  const timer=setTimeout(()=>failure(new Error('engine timeout')),150000);
  chooseStrongMove(state,{level:4,rank:settings.rank,komi:settings.komi,onProgress:p=>{if(done||id!==jobId)return;enginePhase=p.phase||enginePhase;const label=enginePhase==='loading'?'급수별 모델 준비 중 · 첫 실행은 잠시 기다려 주세요':p.visits?'용담 수읽기 중 · '+p.visits+'회 탐색':'용담이 깊이 생각하고 있습니다';$('board-message').textContent=label;$('turn-status').lastElementChild.textContent=label;}}).then(r=>{clearTimeout(timer);if(r.index!==-1&&!play(state,r.index).ok)throw new Error('illegal move');finish(r.index,r)}).catch(e=>{clearTimeout(timer);failure(e)});
  return;
 }
 const fail=()=>{if(done||id!==jobId)return;try{finish(chooseMove(state,settings.level))}catch(e){failure(e)}};
 try{worker=new Worker('./ai-worker.js',{type:'module'});worker.onmessage=e=>{if(e.data.id!==id)return;if(e.data.error){fail();return}finish(e.data.index)};worker.onerror=fail;worker.postMessage({id,state,level:settings.level});setTimeout(()=>{if(!done&&id===jobId)fail()},5000)}catch{setTimeout(fail,30)}
}
function queueAI(){if(state.toPlay!==settings.color&&!state.finished&&!result&&!review){const expected=jobId;setTimeout(()=>{if(jobId===expected)runAI('move')},420)}}
function makeMove(index,computer=false){if(review||result||state.finished||(!computer&&(busy||state.toPlay!==settings.color)))return;const r=play(state,index);if(!r.ok){toast(r.error);return}state=r.state;states.push(state);pending=null;hintIndex=null;if(index>=0)stoneSound();else toast(computer?'용담이 한 수 쉬었습니다.':'한 수 쉬었습니다.');persist();render();queueAI()}
function coord(i,size){return i<0?'한 수 쉼':letters[i%size]+(size-Math.floor(i/size))}
function stoneSound(){if(!sound)return;try{const ctx=stoneSound.ctx||(stoneSound.ctx=new (window.AudioContext||window.webkitAudioContext)());ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(790,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(190,ctx.currentTime+.055);g.gain.setValueAtTime(.12,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.065);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.07)}catch{}}
function boardPick(index){if(review&&quizActive){answerQuiz(index);return}if(review){toast('복기 중입니다. 아래 화살표로 수순을 살펴보세요.');return}if(state.finished&&!result){const g=groupAt(state.board,index,state.size);if(!g.stones.length)return;const remove=dead.has(index);g.stones.forEach(p=>remove?dead.delete(p):dead.add(p));persist();render();return}if(result)return;if(busy||state.toPlay!==settings.color){toast((settings.level>=4?'용담이 깊이 생각하고 있습니다.':'용담이 생각하고 있습니다.'));return}const check=play(state,index);if(!check.ok){toast(check.error);return}if(settings.confirm){pending=index;render()}else makeMove(index)}
function svgNode(tag,attrs={},text){const el=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));if(text!==undefined)el.textContent=text;return el}
function displayState(){return review?(variationStates?.[variationStep]||review.states[reviewIndex]):state}
function renderBoard(){const s=displayState(),n=s.size,svg=$('board'),pad=35,step=570/(n-1),r=step*.465;svg.replaceChildren();svg.setAttribute('aria-label',n+'줄 바둑판, '+s.moves.length+'수. 방향키와 엔터로 착수');const defs=svgNode('defs');defs.innerHTML='<radialGradient id="blackStone" cx="32%" cy="24%" r="75%"><stop offset="0" stop-color="#535754"/><stop offset=".5" stop-color="#282b29"/><stop offset="1" stop-color="#0e1310"/></radialGradient><radialGradient id="whiteStone" cx="32%" cy="25%" r="80%"><stop offset="0" stop-color="#fffefa"/><stop offset=".6" stop-color="#f6f4ed"/><stop offset="1" stop-color="#cccfc5"/></radialGradient><filter id="stoneShadow" x="-25%" y="-25%" width="150%" height="160%"><feDropShadow dx="1" dy="2" stdDeviation="1.2" flood-color="#493518" flood-opacity=".3"/></filter>';svg.append(defs);
const grid=svgNode('g',{'stroke':'#876c43','stroke-width':n===19?.9:1.1,'opacity':.8});for(let i=0;i<n;i++){let p=pad+i*step;grid.append(svgNode('line',{x1:pad,y1:p,x2:605,y2:p}),svgNode('line',{x1:p,y1:pad,x2:p,y2:605}));if(coords){for(const y of [17,625])svg.append(svgNode('text',{x:p,y,fill:'#92754b','font-size':11,'font-family':'Georgia,serif','text-anchor':'middle'},letters[i]));for(const x of [16,625])svg.append(svgNode('text',{x,y:p+4,fill:'#92754b','font-size':11,'font-family':'Georgia,serif','text-anchor':'middle'},n-i))}}svg.append(grid);const star=n===9?[2,4,6]:n===13?[3,6,9]:[3,9,15];for(const y of star)for(const x of star){if(n===9&&(x===4)!==(y===4))continue;svg.append(svgNode('circle',{cx:pad+x*step,cy:pad+y*step,r:n===19?2.8:3.3,fill:'#745c37'}))}
const moveNo=new Map();s.moves.forEach((m,k)=>{if(m.index>=0){m.captured?.forEach(p=>moveNo.delete(p));moveNo.set(m.index,k+1)}});const scoring=!review&&s.finished&&!result;let tally=scoring?score(s,settings.komi,[...dead]):null;const visibleDead=review?new Set(reviewIndex===review.states.length-1?(review.record.dead||[]):[]):dead;
for(let i=0;i<n*n;i++){const cx=pad+(i%n)*step,cy=pad+Math.floor(i/n)*step,c=s.board[i];if(c){const g=svgNode('g',{'opacity':visibleDead.has(i)?.32:1});g.append(svgNode('circle',{cx,cy,r,fill:c===1?'url(#blackStone)':'url(#whiteStone)',filter:'url(#stoneShadow)'}));if(numbers&&moveNo.has(i)){g.append(svgNode('text',{x:cx,y:cy+step*.12,'font-size':step*.38,'font-family':'system-ui,sans-serif','text-anchor':'middle',fill:c===1?'#f4f1e6':'#455347'},moveNo.get(i)))}else if(i===s.lastMove){g.append(svgNode('circle',{cx,cy,r:r*.25,fill:'none',stroke:c===1?'#d7dfd0':'#657953','stroke-width':1.7}))}svg.append(g)}else if(tally?.ownership[i])svg.append(svgNode('rect',{x:cx-3.2,y:cy-3.2,width:6.4,height:6.4,fill:tally.ownership[i]===1?'#283329':'#fffdf3',opacity:.7}));if(!review&&i===hintIndex)svg.append(svgNode('circle',{cx,cy,r:r*.65,fill:'#78975b55',stroke:'#486e36','stroke-width':2,'stroke-dasharray':'4 3'}));if(!review&&i===pending)svg.append(svgNode('circle',{cx,cy,r,fill:settings.color===1?'#172d1d':'#fffdf4',opacity:.4,stroke:'#406836','stroke-width':2}));}
const focusX=pad+(focusIndex%n)*step,focusY=pad+Math.floor(focusIndex/n)*step;if(document.activeElement===svg)svg.append(svgNode('rect',{x:focusX-step*.5,y:focusY-step*.5,width:step,height:step,fill:'none',stroke:'#466f3e','stroke-width':2,'stroke-dasharray':'3 2'}));
}
function render(){const s=displayState(),opt=review?review.settings:settings,lv=LEVELS[opt.level],finished=!!result,scoring=state.finished&&!result&&!review;renderBoard();$('size-label').textContent=s.size+'줄';$('opponent-level').textContent=rankLabel(opt)+' 기풍으로 두는 연습 상대';$('level-label').textContent=rankLabel(opt)+' · 연습 대국';$('human-color').textContent=opt.color===1?'흑 · '+(opt.handicap?'접돌 '+opt.handicap+'점':'먼저 둡니다'):'백 · 덤 '+opt.komi+'집';$('ai-color').textContent=opt.color===1?'백 · 덤 '+opt.komi+'집':'흑 · '+(opt.handicap?'접돌 '+opt.handicap+'점':'먼저 둡니다');$('human-stone').className='player-stone '+(opt.color===1?'black':'white');$('ai-stone').className='player-stone '+(opt.color===2?'black':'white');$('human-captures').textContent=s.captures[opt.color];$('ai-captures').textContent=s.captures[3-opt.color];$('move-label').innerHTML='<strong>'+s.moves.length+'</strong> 수';$('engine-badge').textContent=rankLabel(opt);$('search-stats').textContent=engineStats&&!review?'최근 수읽기 '+engineStats.visits+'회 · '+(engineStats.elapsedMs/1000).toFixed(1)+'초':opt.level>=4?'학습 모델 + 수읽기 · 오프라인':'기초 연습 엔진 · 오프라인';$('rules-summary').textContent=(opt.handicap?opt.handicap+'점 접바둑':'호선')+' · 덤 '+opt.komi+'집 · 면적 계산';$('game-mode').textContent=review?'기보 복기':finished?'대국 종료':'컴퓨터와 연습 대국';let message=review?'수순을 되짚으며 천천히 살펴보세요.':finished?result.label:scoring?'죽은 돌을 표시하고 계가를 확정하세요.':busy?(jobKind==='hint'?'도움 한 수를 찾고 있습니다.':(settings.level>=4?'용담이 깊이 생각하고 있습니다.':'용담이 생각하고 있습니다.')):state.toPlay===settings.color?(state.moves.length?'좋은 자리에서, 나의 한 수.':'바둑판을 눌러 첫 수를 두세요.'):'용담의 차례입니다.';$('board-message').textContent=message;$('turn-status').innerHTML='<span class="pulse-dot"></span><span>'+(review?'기보 복기 중':finished?result.label:scoring?'사석 확인 · 계가':busy?(jobKind==='hint'?'도움 한 수 계산 중':'용담 생각 중'):state.toPlay===settings.color?'나의 차례입니다':'용담의 차례입니다')+'</span>';$('turn-status').classList.toggle('thinking',busy);if(engineFailure){$('board-message').textContent='강화 엔진을 다시 준비해 주세요.';$('turn-status').lastElementChild.textContent='엔진 준비 필요'}
$('confirm-bar').hidden=pending===null||!!review||scoring;$('confirm-label').textContent=pending===null?'':coord(pending,state.size)+'에 두시겠습니까?';$('scoring-bar').hidden=!scoring;if(scoring){const t=score(state,settings.komi,[...dead]);$('score-preview').textContent='흑 '+t.black+'집 · 백 '+t.white+'집 (덤 포함)';}$('review-bar').hidden=!review;$('back-live').hidden=!review;$('retry-engine').hidden=!engineFailure||!!review;['pass','hint'].forEach(id=>$(id).disabled=!!review||finished||state.finished||busy||state.toPlay!==settings.color);$('undo').disabled=!!review||finished||states.length<=1;$('resign').disabled=!!review||finished||state.finished;$('change-level').disabled=!!review;$('review-start').disabled=$('review-prev').disabled=reviewIndex===0;$('review-end').disabled=$('review-next').disabled=!review||reviewIndex===review.states.length-1;if(review){$('review-range').max=review.states.length-1;$('review-range').value=reviewIndex;$('review-position').textContent=reviewIndex+' / '+(review.states.length-1)}$('coordinates').classList.toggle('on',coords);$('coordinates').setAttribute('aria-pressed',coords);$('numbers').classList.toggle('on',numbers);$('numbers').setAttribute('aria-pressed',numbers);$('sound').classList.toggle('on',sound);$('sound').setAttribute('aria-pressed',sound);renderStudy()}
function setup(){const opt=settings;$('level-select').value=rankFor(opt);$('size-select').value=opt.size;$('color-select').value=opt.color;$('handicap-select').value=opt.handicap;$('komi-select').value=opt.komi;$('confirm-touch').checked=opt.confirm;updateSetup();$('setup-dialog').showModal()}
function updateSetup(){$('level-description').textContent='선택한 급·단의 사람 기풍을 참고하는 연습입니다. 한게임·오로의 동일 기력을 보장하지 않습니다.';for(const o of $('handicap-select').options)o.disabled=+$('size-select').value===9&&+o.value>5;if(+$('size-select').value===9&&+$('handicap-select').value>5)$('handicap-select').value='5'}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderArchive(){const records=[...archive];if(state.moves.length&&!records.some(r=>r.id===gameId))records.unshift(record());if(!records.length){$('archive-list').innerHTML='<div class="archive-empty"><h2>첫 번째 기보를 기다리고 있습니다.</h2><p>대국을 시작하면 한 수 한 수, 자동으로 기록됩니다.</p><button class="button primary" id="empty-start">첫 대국 두러 가기 ↗</button></div>';$('empty-start').onclick=()=>showTab('play');return}$('archive-list').className='archive-list';$('archive-list').replaceChildren();records.forEach(rec=>{const card=document.createElement('article');card.className='archive-item';const lv=LEVELS[rec.settings.level]||LEVELS[0];card.innerHTML='<div class="archive-symbol"><span class="player-stone black"></span><span class="player-stone white"></span></div><div class="archive-info"><h3>'+escapeHTML((rec.result?.label||(rec.id===gameId?'진행 중인 대국':'연습 대국')).replaceAll('용담'+' 선생','용담'))+'</h3><p>'+escapeHTML(new Date(rec.date).toLocaleString('ko-KR',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}))+' · '+rec.settings.size+'줄 · '+escapeHTML(rankLabel(rec.settings))+' · '+rec.moves.length+'수</p></div>';const actions=document.createElement('div');actions.className='archive-actions';for(const [label,fn] of [['복기',()=>openReview(rec)],['AI 복기',()=>{openReview(rec);$('study-panel').scrollIntoView({behavior:'smooth',block:'center'})}],['SGF 저장',()=>downloadSGF(rec)]]){const b=document.createElement('button');b.className='button';b.textContent=label;b.onclick=fn;actions.append(b)}card.append(actions);$('archive-list').append(card)})}
function openReview(rec){try{cancelAI();review={...rebuild(rec),record:rec};reviewIndex=review.states.length-1;loadStudy();pending=null;showTab('play');render();window.scrollTo({top:0,behavior:'smooth'})}catch{toast('이 기보를 읽을 수 없습니다.')}}
function sgf(rec){const opt=rec.settings,initial=newGame(opt.size,opt.handicap),esc=v=>String(v).replace(/\\/g,'\\\\').replace(/]/g,'\\]');let text='(;GM[1]FF[4]CA[UTF-8]AP[YongdamBaduk:'+APP_VERSION+']SZ['+opt.size+']KM['+opt.komi+']RU[Chinese]DT['+rec.date.slice(0,10)+']PB['+(opt.color===1?'나':'용담')+']PW['+(opt.color===2?'나':'용담')+']C[용담바둑 로컬 연습 대국. 난이도 '+esc(rankLabel(opt))+'.]';const point=i=>String.fromCharCode(97+i%opt.size)+String.fromCharCode(97+Math.floor(i/opt.size));if(opt.handicap)text+='HA['+opt.handicap+']AB'+initial.board.flatMap((v,i)=>v===1?'['+point(i)+']':[]).join('')+'PL[W]';if(rec.result)text+='RE['+(rec.result.winner?(rec.result.winner===1?'B':'W')+'+'+(rec.result.reason==='resign'?'R':rec.result.margin):'0')+']';let color=opt.handicap?2:1;for(const index of rec.moves){text+=';'+(color===1?'B':'W')+'['+(index<0?'':point(index))+']';color=3-color}return text+')'}
function downloadSGF(rec){const blob=new Blob([sgf(rec)],{type:'application/x-go-sgf;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='용담바둑_'+rec.date.slice(0,10)+'_'+rec.moves.length+'수.sgf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('SGF 기보를 내려받습니다.')}
function installGuide(){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.finally(()=>{installPrompt=null});return}info('용담바둑을 앱처럼 사용하기','<p><strong>먼저 ‘오프라인 준비 완료’를 확인하세요.</strong></p><ol><li>Android Chrome: 브라우저 메뉴 → ‘앱 설치’ 또는 ‘홈 화면에 추가’</li><li>iPhone / iPad Safari: 공유 → ‘홈 화면에 추가’</li><li>PC Chrome / Edge: 주소창의 설치 아이콘 또는 메뉴의 앱 설치</li></ol><p>ChatGPT 안에서 설치 메뉴가 보이지 않으면 이 사이트를 외부 브라우저에서 열어 주세요. 설치 후 비행기 모드에서도 대국할 수 있습니다. 브라우저의 사이트 데이터를 삭제하면 다시 연결해 준비해야 합니다.</p>')}
function renderConnection(){const el=$('connection');el.classList.toggle('warning',!offlineReady);el.innerHTML='<span class="status-dot"></span><span>'+(offlineReady?(navigator.onLine?'오프라인 준비 완료':'오프라인 대국 가능'):(navigator.onLine?'오프라인 준비 중':'첫 연결이 필요합니다'))+'</span>'}
async function prepareOffline(){renderConnection();if(!('serviceWorker'in navigator)){offlineFailure();return}try{const registration=await navigator.serviceWorker.register('./sw.js');const watch=worker=>{worker?.addEventListener('statechange',()=>{if(worker.state==='redundant'&&!offlineReady)offlineFailure()})};watch(registration.installing);registration.addEventListener('updatefound',()=>watch(registration.installing));navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='CACHE_STATUS'){offlineReady=!!e.data.ready&&e.data.version==='v'+APP_VERSION;renderConnection()}});const reg=await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error('offline-timeout')),180000))]);const ch=new MessageChannel();ch.port1.onmessage=e=>{offlineReady=!!e.data.ready&&e.data.version==='v'+APP_VERSION;renderConnection()};reg.active?.postMessage({type:'CACHE_STATUS'},[ch.port2]);}catch{offlineFailure()}}
function offlineFailure(){$('connection').classList.add('warning');$('connection').innerHTML='<span class="status-dot"></span><span>오프라인 준비 안 됨</span>';}
$('board').addEventListener('click',e=>{const p=$('board').createSVGPoint();p.x=e.clientX;p.y=e.clientY;const pt=p.matrixTransform($('board').getScreenCTM().inverse()),n=displayState().size,step=570/(n-1),x=Math.round((pt.x-35)/step),y=Math.round((pt.y-35)/step);if(x<0||x>=n||y<0||y>=n)return;focusIndex=y*n+x;boardPick(focusIndex)});
$('board').addEventListener('keydown',e=>{const n=displayState().size;let x=focusIndex%n,y=Math.floor(focusIndex/n);if(e.key==='ArrowLeft')x=Math.max(0,x-1);else if(e.key==='ArrowRight')x=Math.min(n-1,x+1);else if(e.key==='ArrowUp')y=Math.max(0,y-1);else if(e.key==='ArrowDown')y=Math.min(n-1,y+1);else if(e.key==='Enter'||e.key===' '){e.preventDefault();boardPick(focusIndex);return}else return;e.preventDefault();focusIndex=y*n+x;renderBoard()});$('board').onfocus=renderBoard;$('board').onblur=renderBoard;
$('confirm-move').onclick=()=>{if(pending!==null)makeMove(pending)};$('cancel-move').onclick=()=>{pending=null;render()};$('pass').onclick=()=>{pending=null;makeMove(-1)};$('hint').onclick=()=>{pending=null;runAI('hint')};$('undo').onclick=()=>{cancelAI();let target=states.length-2;while(target>0&&states[target].toPlay!==settings.color)target--;states=states.slice(0,target+1);state=states.at(-1);pending=null;hintIndex=null;dead=new Set();persist();render();queueAI();toast('나의 착수 전으로 돌아왔습니다.')};$('resign').onclick=()=>info('이번 대국을 마치시겠습니까?','<p>기권해도 지금까지의 기보는 보관함에 남습니다.</p>',[{label:'계속 두기'},{label:'기권하기',primary:true,action:()=>{cancelAI();result={winner:3-settings.color,reason:'resign',label:(settings.color===1?'백':'흑')+' 불계승 · 용담 승'};pending=null;persist();render()}}]);
$('finish-score').onclick=()=>{const t=score(state,settings.komi,[...dead]);result={...t,reason:'score',label:t.winner?(t.winner===1?'흑':'백')+' '+t.margin+'집 승':'무승부'};persist();render();info('수고하셨습니다', '<p><strong>'+result.label+'</strong></p><p>흑 '+t.black+'집 · 백 '+t.white+'집 (덤 포함)</p><p>기보 보관함에서 이번 대국을 다시 살펴보세요.</p>',[{label:'기보 복기',action:()=>openReview(record())},{label:'새 대국',primary:true,action:setup}])};$('resume-game').onclick=()=>{states=states.slice(0,-2);state=states.at(-1);dead=new Set();persist();render();queueAI()};
['new-game','change-level','open-settings'].forEach(id=>$(id).onclick=setup);$('level-select').innerHTML=RANKS.map(r=>'<option value="'+r.id+'">'+r.label+'</option>').join('');$('level-select').onchange=updateSetup;$('size-select').onchange=updateSetup;$('handicap-select').onchange=()=>{if(+$('handicap-select').value){$('komi-select').value='0.5';$('color-select').value='1'}else $('komi-select').value='6.5';updateSetup()};$('setup-form').onsubmit=e=>{e.preventDefault();saveArchive(record());const opt={size:+$('size-select').value,level:6,rank:$('level-select').value,color:+$('color-select').value,handicap:+$('handicap-select').value,komi:+$('komi-select').value,confirm:$('confirm-touch').checked};$('setup-dialog').close();showTab('play');reset(opt);toast('새 대국을 시작합니다.')};
$('coordinates').onclick=()=>{coords=!coords;render()};$('numbers').onclick=()=>{numbers=!numbers;render()};$('sound').onclick=()=>{sound=!sound;render();if(sound)stoneSound()};$('export-sgf').onclick=()=>downloadSGF(review?review.record:record());$('back-live').onclick=()=>{stopReviewAnalysis();review=null;render();queueAI()};const seek=i=>{if(review){stopReviewAnalysis();variationStates=null;quizActive=false;reviewIndex=Math.max(0,Math.min(review.states.length-1,i));render()}};$('review-start').onclick=()=>seek(0);$('review-prev').onclick=()=>seek(reviewIndex-1);$('review-next').onclick=()=>seek(reviewIndex+1);$('review-end').onclick=()=>seek(review.states.length-1);$('review-range').oninput=e=>seek(+e.target.value);
$('retry-engine').onclick=()=>runAI(jobKind);$('install').onclick=installGuide;$('guide-install').onclick=installGuide;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('appinstalled',()=>toast('용담바둑이 설치되었습니다.'));['online','offline'].forEach(type=>window.addEventListener(type,renderConnection));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('.nav-button').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));document.querySelector('.brand').onclick=e=>{e.preventDefault();showTab('play')};window.addEventListener('hashchange',()=>{const tab=location.hash.slice(1);if(['play','guide','archive'].includes(tab))showTab(tab)});
let studyData={},studyController=null,studyStatus='',variationStates=null,variationStep=0,quizActive=false,quizAnswerShown=false;
const STUDY_KEY='yongdam-study-v1';
function stopReviewAnalysis(){studyController?.abort();studyController=null;variationStates=null;quizActive=false;studyStatus=''}
function loadStudy(){variationStates=null;quizActive=false;const stored=safeRead(STUDY_KEY,{});studyData=stored?.[review.record.id]?.signature===recordSignature(review.record)?stored[review.record.id].moments||{}:{}}
function saveStudy(){const stored=safeRead(STUDY_KEY,{});stored[review.record.id]={signature:recordSignature(review.record),moments:studyData};const ids=Object.keys(stored);while(ids.length>30)delete stored[ids.shift()];saveStorage(STUDY_KEY,stored)}
function currentMoment(){return studyData[Math.max(1,reviewIndex)]}
function renderStudy(){const panel=$('study-panel');panel.hidden=!review;if(!review)return;const running=!!studyController,m=currentMoment();$('study-status').textContent=studyStatus||'용담이 추천 수와 실수 후보를 찾아드립니다. 분석값은 짧은 탐색에 따른 추정입니다.';['analyze-position','scan-mistakes'].forEach(id=>$(id).disabled=running);$('study-stop').hidden=!running;$('variation-play').disabled=!m||running;$('quiz-start').disabled=!m||m.loss<2||m.actual===m.best||running;$('variation-prev').disabled=!variationStates||variationStep===0;$('variation-next').disabled=!variationStates||variationStep>=variationStates.length-1;$('quiz-reveal').hidden=!quizActive;
 const content=$('study-result');content.replaceChildren();if(m&&!quizActive){const p=document.createElement('p');p.className='study-summary';p.textContent=m.turn+'수 · '+m.label+' · 예상 손실 '+m.loss.toFixed(1)+'집';content.append(p);const detail=document.createElement('p');detail.textContent='실전 '+coord(m.actual,review.settings.size)+' → 추천 '+coord(m.best,review.settings.size)+' · 흑 예상 승률 '+(m.blackWinRate*100).toFixed(0)+'% · '+m.visits+'회 탐색';content.append(detail);const pv=document.createElement('p');pv.textContent='추천 변화: '+(m.pv.join(' → ')||coord(m.best,review.settings.size))+(variationStates?' · '+variationStep+'/'+(variationStates.length-1)+'수':'');content.append(pv);}
 if(quizActive){const p=document.createElement('p');p.textContent=quizAnswerShown?'추천은 '+coord(m.best,review.settings.size)+'입니다. ‘추천 변화 보기’로 수순을 살펴보세요.':'실전 '+m.turn+'수 직전입니다. 더 좋은 자리를 바둑판에서 골라 보세요.';content.append(p)}
 const list=$('mistake-list');list.replaceChildren();Object.values(studyData).filter(m=>m.loss>=2&&m.best!==m.actual).sort((a,b)=>b.loss-a.loss).forEach(m=>{const b=document.createElement('button');b.className='button';b.textContent=m.turn+'수 · 약 '+m.loss.toFixed(1)+'집 손실';b.onclick=()=>{stopReviewAnalysis();reviewIndex=m.turn;render()};list.append(b)});
}
async function analyzeTurn(turn,signal){const before=review.states[turn-1],after=review.states[turn],opt=review.settings;const analysis=await analyzeStrongPosition(before,{level:6,komi:opt.komi,visits:64,maxTimeMs:3500,signal});const actual=after.moves.at(-1).index;const candidate=analysis.moves.find(m=>(m.x<0||m.y<0?-1:m.y*before.size+m.x)===actual);const next=candidate?null:await analyzeStrongPosition(after,{level:6,komi:opt.komi,visits:64,maxTimeMs:3500,signal});return reviewMoment(before,after,analysis,next)}
async function analyzeStudy(scan=false){if(!review||studyController)return;const turns=scan?review.states.slice(1).map((s,i)=>i+1).filter(t=>review.states[t-1].toPlay===review.settings.color&&!studyData[t]):[Math.max(1,reviewIndex)];if(!turns.length||review.states.length<2){studyStatus='분석할 착수가 없습니다.';renderStudy();return}const controller=new AbortController();studyController=controller;variationStates=null;quizActive=false;render();try{for(let i=0;i<turns.length;i++){studyStatus=(scan?'내 수 분석 '+(i+1)+' / '+turns.length:'현재 수 분석')+' · '+turns[i]+'수 · 중지해도 완료된 결과는 남습니다.';renderStudy();const m=await analyzeTurn(turns[i],controller.signal);if(controller.signal.aborted)return;studyData[m.turn]=m;saveStudy();}studyStatus='분석 완료 · 결과는 이 기기에 저장되었습니다.';}catch(e){if(e.name!=='AbortError')studyStatus='분석을 완료하지 못했습니다. 다시 시도해 주세요. '+e.message;}finally{if(studyController===controller){studyController=null;render()}}}
function startVariation(){const m=currentMoment();if(!m)return;quizActive=false;reviewIndex=m.turn;const base=review.states[m.turn-1],line=legalLine(base,m.pv.length?m.pv:[coord(m.best,base.size)==='한 수 쉼'?'pass':coord(m.best,base.size)]);variationStates=[base,...line];variationStep=0;render()}
function startQuiz(){const m=currentMoment();if(!m||m.loss<2)return;reviewIndex=m.turn;variationStates=[review.states[m.turn-1]];variationStep=0;quizActive=true;quizAnswerShown=false;render()}
function answerQuiz(index){const m=currentMoment();if(!play(review.states[m.turn-1],index).ok){toast('돌을 둘 수 있는 자리를 골라 주세요.');return}if(index===m.best){quizAnswerShown=true;toast('추천 수를 찾으셨습니다!');renderStudy()}else toast(coord(index,review.settings.size)+'도 생각해 보셨군요. 다시 고르거나 정답을 확인해 보세요.')}
$('analyze-position').onclick=()=>analyzeStudy();$('scan-mistakes').onclick=()=>analyzeStudy(true);$('study-stop').onclick=()=>{stopReviewAnalysis();studyStatus='분석을 중지했습니다. 완료된 결과는 저장되어 있습니다.';render()};$('variation-play').onclick=startVariation;$('quiz-start').onclick=startQuiz;$('quiz-reveal').onclick=()=>{quizAnswerShown=true;renderStudy()};$('variation-prev').onclick=()=>{variationStep=Math.max(0,variationStep-1);render()};$('variation-next').onclick=()=>{variationStep=Math.min(variationStates.length-1,variationStep+1);render()};


archive=safeRead(ARCHIVE,[]);if(!Array.isArray(archive))archive=[];archive=archive.filter(r=>r?.settings&&Array.isArray(r.moves)&&r.id);const saved=safeRead(KEY,null);try{if(!saved)throw new Error();const rebuilt=rebuild(saved);settings=rebuilt.settings;state=rebuilt.state;states=rebuilt.states;gameId=saved.id;createdAt=saved.date;result=saved.result;dead=new Set(saved.dead||[]);render();queueAI()}catch{reset(defaults)}showTab(['play','archive','guide'].includes(location.hash.slice(1))?location.hash.slice(1):'play');prepareOffline();
